bounded_host_request.command:
set -Eeuo pipefail
cid="$(docker ps -q --filter label=com.docker.compose.project=debug-ai --filter label=com.docker.compose.service=debug-ai)"
test -n "$cid"
test "$(docker inspect -f '{{.Image}}' "$cid")" = "$(docker image inspect -f '{{.Id}}' debug-ai-debug-ai:teaching-231a8f47)"
docker exec -i "$cid" sh -c 'umask 077; d=/app/runtime/teaching-batch-20261128-1553; mkdir "$d"; cat > "$d/run.cjs"' <<'JS'
"use strict";
const fs=require("node:fs"),path=require("node:path"),crypto=require("node:crypto");
const {createAiCoreAdapter}=require("/app/server/adapters/ai-core.js");
const {runTeaching,teachingTopics,testSyntheticCode,canTeach}=require("/app/server/command-module/teaching.js");
const root=__dirname,chat="/app/runtime/chat";
const state={schema:"debugai.interactive-teaching-batch/v1",id:path.basename(root),status:"STARTING",total:8,started_at:new Date().toISOString(),cost_usd:0,lessons:[]};
function write(p,x){const tmp=p+"."+crypto.randomUUID()+".tmp";fs.writeFileSync(tmp,JSON.stringify(x),{mode:0o600,flag:"wx"});fs.renameSync(tmp,p);}
function save(){state.updated_at=new Date().toISOString();write(path.join(root,"status.json"),state);}
function active(){for(const d of [chat,"/app/runtime/durable/run-state-v2"]){if(!fs.existsSync(d))continue;for(const n of fs.readdirSync(d).filter(n=>n.endsWith(".json"))){const x=JSON.parse(fs.readFileSync(path.join(d,n)));if(x.turns?.some(t=>t.state==="running")||["RUNNING","QUEUED","RETRY_WAIT"].includes(x.job_status))return true;}}return false;}
function safeError(e){return /^[A-Z0-9_]{1,100}$/.test(e?.code||"")?e.code:"TEACHING_BATCH_ERROR";}
(async()=>{
 save();
 const gates=JSON.parse(process.env.DEBUG_AI_COMMAND_MODEL_GATES||"{}");
 const aiCore=createAiCoreAdapter({dispatchMode:"command_only",commandModelGates:gates,commandExternalQualification:process.env.DEBUG_AI_COMMAND_EXTERNAL_QUALIFICATION==="true"});
 if(!canTeach(aiCore))throw Object.assign(Error(),{code:"TEACHING_DEEPSEEK_NOT_CONFIGURED"});
 const budgets={qwen35:Math.min(1024,gates.qwen35.max_output_tokens),deepseek:Math.min(1024,gates.deepseek.max_output_tokens)};
 if(fs.lstatSync(chat).isSymbolicLink())throw Error("CHAT_STORE_INVALID");
 state.status="RUNNING";save();
 for(const topic of teachingTopics()){
  if(active()){state.status="PAUSED_EXISTING_CHAT_OR_JOB";break;}
  if(state.cost_usd===null||state.cost_usd>=0.10){state.status="PAUSED_COST_LIMIT_OR_UNKNOWN";break;}
  const id=crypto.randomUUID(),turn={id,user:"自動学習（Masterの依頼）: "+topic.label,state:"running",interaction_mode:"teaching",mode:"teaching",topic:topic.id,teaching:{stages:[],phase:null,kb_status:"NOT_CONNECTED",weight_update:false}},item={id,title:"自主学習｜"+topic.label,updated_at:new Date().toISOString(),turns:[turn]};
  const row={topic:topic.id,label:topic.label,id,status:"RUNNING",phase:null,teacher_calls:0,cost_usd:0};state.lessons.push(row);save();
  const out=path.join(root,id+".json");
  try{
   const result=await runTeaching({aiCore,topic:topic.id,deadlineAt:Date.now()+600000,maxTokensByModel:budgets,sandbox:code=>testSyntheticCode(code,{runtimeRoot:root}),onStage:s=>{row.phase=s.phase;turn.teaching.phase=s.phase;if(s.state!=="running"){turn.teaching.stages.push(s);if(s.model==="deepseek"){row.teacher_calls++;if(typeof s.cost==="number"&&Number.isFinite(s.cost)){if(row.cost_usd!==null)row.cost_usd+=s.cost;if(state.cost_usd!==null)state.cost_usd+=s.cost;}else{row.cost_usd=null;state.cost_usd=null;}}}write(out,item);save();}});
   turn.teaching=result;turn.state="complete";turn.answer=result.verdict+" / "+result.verification+" / KB未接続・重み更新なし";row.status="COMPLETE";row.verdict=result.verdict;row.verification=result.verification;
  }catch(e){turn.state="failed";turn.error=safeError(e);row.status="FAILED";row.error=turn.error;}
  item.updated_at=new Date().toISOString();write(out,item);
  fs.linkSync(out,path.join(chat,id+".json"));row.chat_history_saved=true;save();
  if(state.cost_usd===null){state.status="PAUSED_COST_UNKNOWN";break;}
 }
 if(state.status==="RUNNING")state.status="FINISHED";save();
})().catch(e=>{state.status="FAILED";state.error=safeError(e);save();process.exitCode=1;});
JS
docker exec -d "$cid" node /app/runtime/teaching-batch-20261128-1553/run.cjs
for n in $(seq 1 10);do if docker exec "$cid" test -s /app/runtime/teaching-batch-20261128-1553/status.json;then echo TEACHING_BATCH_STARTED;exit 0;fi;sleep 1;done
exit 7
